mapper.select:
select 
	t.job_id,
	t.task_id,
	t.task_dim_entities,
	t.lean_job_id,
	t.lean_task_id,
	t.lean_task_dim_entities
from ww_task_special_lean t
where
	t.job_id = #{jobId}

	and t.task_id = #{taskId}


	and t.task_dim_entities = #{taskDimEntities}


	and (t.lean_job_id is null or t.job_id=t.lean_job_id)


	and t.lean_task_id = #{leanTaskId}


	and t.lean_task_dim_entities = #{leanTaskDimEntities}

